        }

if type42_sfnt_data(data).is_some() {
    return Self::type42_face(data, face_index, size_pt);
}
if type1_cleartext(data).is_some() {
    return Self::type1_face(data, face_index, size_pt);
}
if data.len() >= 17 && data.iter().all(|byte| *byte < b' ') {
    // FreeType's final BDF driver probe (`bdf/bdflib.c`) skips every
    // byte below ASCII space while looking for a line.  An all-
    // control stream therefore reaches EOF with no `STARTFONT`
    // line and returns Invalid_File_Format from `bdf_load_font`;
    // `BDF_Face_Init` preserves that error for `FT_Open_Face`.
    // Keep the length guard because earlier C driver probes use
    // fixed-size frames and win the error race on shorter streams.
    return Err(FontError::InvalidFileFormat(
        "BDF stream ended before a complete line".into(),
    ));
}

    match Self::truetype_face(data, face_index, size_pt) {
        Ok(face) => Ok(face),
        Err(error) if data.len() >= 118 => {
            // FreeType's WinFNT driver tries a standalone FNT header
            // after its MZ/NE probe fails. Its unknown-format result is
            // the final face-open error for a structurally plausible FNT
            // header with an unsupported version; unrelated malformed
            // buffers retain the earlier SFNT parser error.
            match Self::winfnt_face(data, face_index, size_pt) {
                Ok(face) => Ok(face),
                Err(FontError::UnknownFileFormat(message)) if has_winfnt_header_shape(data) => {
                    Err(FontError::UnknownFileFormat(message))
                }
                Err(_) => Err(error),
            }
        }
        Err(error) => Err(error),
    }
}

fn truetype_face_with_load_mode_and_design_coords(
        data: &[u8],
        face_index: usize,
        size_pt: f32,
        load_mode: LoadMode,
        design_coords: Option<&[i32]>,
        blend_coords_16_16: Option<&[i32]>,
        variation_coordinates_set: bool,
    ) -> Result<Self, FontError> {
        // FreeType stores a 1-based named-instance selector in bits 16..30;
        // the low 16 bits still select the collection face (ftobjs.c).
        let collection_face_index = face_index & 0xFFFF;
        let (num_faces, face_offset) = tt::resolve_face_index(data, collection_face_index)?;
        let dir = tt::parse_table_directory_at(data, face_offset)?;
        let fvar = dir
            .find(data, tag(b"fvar"))
            .and_then(|bytes| tt::fvar::parse_fvar(bytes).ok());
        let avar = fvar.as_ref().and_then(|fvar| {
            dir.find(data, tag(b"avar"))
                .and_then(|bytes| tt::avar::parse_avar(bytes, fvar.axes.len()).ok())
        });

let named_instance = (face_index >> 16) & 0x7FFF;
if named_instance != 0
    && fvar
        .as_ref()
        .is_none_or(|table| named_instance > usize::from(table.instance_count))
{
    return Err(FontError::InvalidFont(format!(
        "named instance {named_instance} is unavailable"
    )));
}

let head_bytes = dir
    .find(data, tag(b"head"))
    .ok_or_else(|| FontError::InvalidFont("missing 'head' table".into()))?;
let head = tt::head::parse_head(head_bytes)?;

// tt_face_load_maxp reads its optional 26-byte frame from the SFNT
// stream after goto_table, without constraining reads to table length.
let maxp_record = dir
    .record(tag(b"maxp"))
    .ok_or_else(|| FontError::InvalidFont("missing 'maxp' table".into()))?;
let maxp_bytes = data
    .get(maxp_record.offset as usize..)

    .ok_or_else(|| FontError::InvalidFont("invalid 'maxp' table offset".into()))?;
// sfnt_load_face intentionally continues after a maxp load error.
let maxp = tt::maxp::parse_maxp(maxp_bytes).unwrap_or_default();

let cmap_bytes = dir
    .find(data, tag(b"cmap"))
    .ok_or_else(|| FontError::InvalidFont("missing 'cmap' table".into()))?;
// `sfnt_load_face` keeps the face usable when the cmap service cannot
// build any charmap records.  The malformed table remains observable
// as an empty public charmap list instead of aborting face creation.
let cmap = tt::cmap::parse_cmap(cmap_bytes).unwrap_or_default();

let hhea_bytes = dir
    .find(data, tag(b"hhea"))
    .ok_or_else(|| FontError::InvalidFont("missing 'hhea' table".into()))?;
let hhea = tt::hhea::parse_hhea(hhea_bytes)?;

let hmtx_bytes = dir
    .find(data, tag(b"hmtx"))

fn normalize_load_flags(font: &Font, mut flags: LoadFlags) -> LoadFlags {
        let metrics = font.size_metrics();
        // FreeType resolves these dependencies in `FT_Load_Glyph` before driver
        // load (`src/base/ftobjs.c:932-952`).  Keep this in core so Rust, C ABI,
        // and WASM public entry points all exercise the same policy.
        if metrics.x_ppem == 0 || metrics.y_ppem == 0 {
            flags |= LoadFlags::NO_SCALE;
        }
        if flags.contains(LoadFlags::NO_RECURSE) {
            flags |= LoadFlags::NO_SCALE;
        }
        if flags.contains(LoadFlags::NO_SCALE) {
            flags |= LoadFlags::NO_HINTING | LoadFlags::NO_BITMAP;
            flags = flags.without(LoadFlags::RENDER);
        }
        if flags.contains(LoadFlags::BITMAP_METRICS_ONLY) {
            flags = flags.without(LoadFlags::RENDER);
        }
        flags
    }

    fn load_glyph_from_font(
        font: &Font,
        glyph_index: u16,
        mut flags: LoadFlags,

let svg_only = flags.contains(LoadFlags::SVG_ONLY);
let svg_allowed = flags.contains(LoadFlags::COLOR) && !flags.contains(LoadFlags::NO_SVG);
// `TT_Load_Glyph` converts a missing image from a non-scalable sbix
// face into a successful empty MONO bitmap before trying outlines.
// This must precede the outline path because bitmap-only sbix faces
// intentionally do not expose a usable scalable glyph there.
if let Some(sbit) = font.sbix_missing_bitmap_glyph(glyph_index, font.size_metrics().y_ppem)
{
    let mut slot = empty_sbit_glyph_slot(glyph_index, sbit, vertical_layout);
    if let Some((xx, xy, yx, yy, dx, dy)) = transform {
        slot.apply_transform(xx, xy, yx, yy, dx, dy);
    }
    return Ok(slot);
}
if svg_allowed {
    match font.load_svg_glyph(glyph_index) {
        Ok((metrics, document)) => {
            let mut slot =

                GlyphSlot::from_svg(glyph_index, metrics, document, vertical_layout);
            if let Some((xx, xy, yx, yy, dx, dy)) = transform {
                slot.apply_transform(xx, xy, yx, yy, dx, dy);
            }
            return Ok(slot);
        }
        Err(_) if svg_only => {
            return Err(FontError::InvalidArgument("SVG glyph not available".into()));
        }
        Err(_) => {}
    }
} else if svg_only {
    return Err(FontError::InvalidArgument("SVG glyph not available".into()));
}
// C `truetype/ttgload.c:TT_Load_Glyph` only honors `FT_LOAD_NO_BITMAP`
// for scalable faces: `!(NO_BITMAP && FT_IS_SCALABLE(face))`.  For
// bitmap-only CBLC/CBDT faces, `sfobjs.c` clears SCALABLE and the
// embedded strike is therefore loaded even with `FT_LOAD_NO_BITMAP`.

let sbit_allowed = !(flags.contains(LoadFlags::NO_SCALE)
    || flags.contains(LoadFlags::NO_BITMAP) && font.is_scalable());
if sbits_only && !sbit_allowed {
    return Err(FontError::InvalidArgument(
        "embedded bitmap strike not selected".into(),
    ));
}
if sbit_allowed {
    // C `FT_Load_Glyph` first tries SVG, then embedded bitmaps before
    // outline loading (`base/ftobjs.c:1028-1050`). The TrueType driver
    // repeats that SBIT attempt in `truetype/ttgload.c:2401-2474`.
    match font.load_sbit_only_glyph(glyph_index) {
        Ok(mut sbit) => {
            // `FT_LOAD_BITMAP_METRICS_ONLY` lets the SBIT loader fill
            // metrics and bitmap metadata but skips allocating the
            // image buffer (`sfnt/ttsbit.c:545-588`).
            if !flags.contains(LoadFlags::COLOR)

                && !flags.contains(LoadFlags::BITMAP_METRICS_ONLY)
            {
                sbit.bitmap.flatten_bgra_to_gray()?;
            }
            return Ok(sbit_glyph_slot_with_bitmap(
                glyph_index,
                sbit,
                vertical_layout,
                !flags.contains(LoadFlags::BITMAP_METRICS_ONLY),
            ));
        }
        Err(_) if sbits_only => {
            // For scalable TrueType faces with `FT_LOAD_SBITS_ONLY`,
            // failed SBIT loading is replaced with Invalid_Argument
            // (`truetype/ttgload.c:2467-2474`).
            return Err(FontError::InvalidArgument(
                "embedded bitmap image not available".into(),
            ));
        }
        Err(_) => {}
    }
}

let mut loaded = if flags.contains(LoadFlags::NO_RECURSE) {
    font.glyph_slot_load_no_recurse(glyph_index)?
} else if flags.contains(LoadFlags::NO_SCALE) {
    font.glyph_slot_load_no_scale_with_layout(glyph_index, vertical_layout)?
} else if flags.contains(LoadFlags::NO_HINTING) {
    font.glyph_slot_load_no_hinting(glyph_index)?
} else if flags.contains(LoadFlags::FORCE_AUTOHINT)
    && !flags.contains(LoadFlags::NO_AUTOHINT)
{
    if flags.contains(LoadFlags::TARGET_LIGHT) {
        font.glyph_slot_load_force_autohint_light_with_layout(glyph_index, vertical_layout)?
    } else {
        font.glyph_slot_load_force_autohint_with_layout_and_mode(
            glyph_index,
            vertical_layout,
            native_hint_mode,
        )?
    }

} else if flags.contains(LoadFlags::TARGET_LIGHT) && !flags.contains(LoadFlags::NO_AUTOHINT)
{
    font.glyph_slot_load_target_light(glyph_index, vertical_layout)?
} else if flags.contains(LoadFlags::NO_AUTOHINT) {
    font.glyph_slot_load_no_autohint_with_layout_and_mode_and_pedantic(
        glyph_index,
        vertical_layout,
        native_hint_mode,
        pedantic_hinting,
    )?
} else {
    // C `tt_loader_init` suppresses `size->widthp` when
    // `FT_LOAD_COMPUTE_METRICS` is set (ttgload.c:2299-2305).
    font.glyph_slot_load_default_with_layout_and_mode_and_hdmx_and_pedantic(
        glyph_index,
        vertical_layout,
        native_hint_mode,
        !flags.contains(LoadFlags::COMPUTE_METRICS),
        pedantic_hinting,
    )?
};

let render_requested = flags.contains(LoadFlags::RENDER);
